PRAGMA foreign_keys=ON;
CREATE TABLE IF NOT EXISTS users (id text PRIMARY KEY NOT NULL, email text NOT NULL, password_hash text NOT NULL, created_at integer NOT NULL DEFAULT (unixepoch()));
CREATE UNIQUE INDEX IF NOT EXISTS users_email_uq ON users (email);
CREATE TABLE IF NOT EXISTS devices (id text PRIMARY KEY NOT NULL, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, name text NOT NULL, manufacturer text, model text, android_version text, api_level integer, battery_percent integer, charging integer, app_version text, network_status text, last_seen_at integer, created_at integer NOT NULL DEFAULT (unixepoch()), revoked_at integer);
CREATE INDEX IF NOT EXISTS devices_owner_idx ON devices (owner_id);
CREATE TABLE IF NOT EXISTS pairing_invitations (id text PRIMARY KEY NOT NULL, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, token_hash text NOT NULL, expires_at integer NOT NULL, used_at integer, created_at integer NOT NULL DEFAULT (unixepoch()));
CREATE UNIQUE INDEX IF NOT EXISTS pairing_token_hash_uq ON pairing_invitations (token_hash);
CREATE INDEX IF NOT EXISTS pairing_owner_idx ON pairing_invitations (owner_id);
CREATE TABLE IF NOT EXISTS remote_sessions (id text PRIMARY KEY NOT NULL, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_id text NOT NULL REFERENCES devices(id) ON DELETE CASCADE, room_name text NOT NULL, status text NOT NULL DEFAULT 'active', expires_at integer NOT NULL, revoked_at integer, created_at integer NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS sessions_owner_idx ON remote_sessions (owner_id);
CREATE INDEX IF NOT EXISTS sessions_device_idx ON remote_sessions (device_id);
CREATE TABLE IF NOT EXISTS device_permissions (id text PRIMARY KEY NOT NULL, device_id text NOT NULL REFERENCES devices(id) ON DELETE CASCADE, capability text NOT NULL, granted integer NOT NULL DEFAULT 0, updated_at integer NOT NULL DEFAULT (unixepoch()));
CREATE UNIQUE INDEX IF NOT EXISTS device_permission_uq ON device_permissions (device_id, capability);
CREATE TABLE IF NOT EXISTS security_audit_events (id text PRIMARY KEY NOT NULL, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_id text REFERENCES devices(id) ON DELETE SET NULL, event_type text NOT NULL, details text NOT NULL DEFAULT '{}', created_at integer NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS audit_owner_created_idx ON security_audit_events (owner_id, created_at);
CREATE TABLE IF NOT EXISTS file_transfer_records (id text PRIMARY KEY NOT NULL, owner_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, device_id text NOT NULL REFERENCES devices(id) ON DELETE CASCADE, direction text NOT NULL, file_name text NOT NULL, status text NOT NULL, created_at integer NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS transfers_owner_created_idx ON file_transfer_records (owner_id, created_at);
CREATE TABLE IF NOT EXISTS auth_sessions (id text PRIMARY KEY NOT NULL, user_id text NOT NULL REFERENCES users(id) ON DELETE CASCADE, csrf_hash text NOT NULL, expires_at integer NOT NULL, revoked_at integer, created_at integer NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS auth_sessions_user_idx ON auth_sessions (user_id);
CREATE TABLE IF NOT EXISTS login_attempts (id text PRIMARY KEY NOT NULL, lookup_hash text NOT NULL, attempted_at integer NOT NULL DEFAULT (unixepoch()));
CREATE INDEX IF NOT EXISTS login_attempts_lookup_time_idx ON login_attempts (lookup_hash, attempted_at);
